      claimed: 0,
      sent: 0,
      skipped: 0,
      throttled: 0,
      endpointFailures: 0,
      rowFailures: 0,
      breakerOpen: this.isBreakerOpen,
      callsMade: this.governor.grantedCount - callsBefore,
    };
  }
}
