  }

  /** Decide what to send for one record, or that nothing is owed. */
  private planCall(
    tx: Tx,
    batch: RecordBatch,
  ):
    | { kind: "call"; sfId: string | null; values: Record<string, string | null> }
    | { kind: "nothing-owed" } {
